export default function PrivacyPage() { return <main className="section directory-page prose"><h1>Privacy</h1><p>Khanti Koraputia stores account, listing, enquiry, review and saved-discovery data needed to operate this community platform. Do not submit information you do not want stored.</p><h2>Contact information</h2><p>Information submitted through enquiries is stored so the platform team or relevant listing owner can respond.</p><h2>Accounts</h2><p>Passwords are stored as cryptographic hashes. Sessions use secure, HttpOnly cookies.</p><h2>Your requests</h2><p>You may contact the platform team to request correction or deletion of your account data, subject to operational and legal requirements.</p></main>; }
